// A stub standing in for @types/titanium. It mirrors the real package's shape — a Titanium
// namespace of classes with a `Ti` alias, JSDoc on the members, and inheritance through extends
// rather than flattened — but not its size: the real index.d.ts is 2.3MB and 66k lines, and
// committing it would say nothing the resolution and host tests do not.
//
// The version in package.json is deliberately 9.2.2 while classic-project's tiapp says 12.4.0.GA,
// so a test can tell "the project's own copy won" from "the version rule picked a 12.x".

declare namespace Titanium {
	namespace UI {
		class View {
			backgroundColor: string;
			add (view: View): void;
			addEventListener (name: string, callback: () => void): void;
		}

		// the real package gives each class an EventMap and an addEventListener overload keyed on
		// it, which is what makes `addEventListener('` offer event names. Mirrored here so a test
		// can hold that behaviour still
		interface LabelEventMap {
			/** Fired when the device detects a click against the view. */
			click: { source: Label };
			longpress: { source: Label };
		}

		/** A text label, with an optional background image. */
		class Label extends View {
			/** The text to display */
			text: string;
			color: string;
			// what the platform reports rather than accepts, which the real package marks readonly
			// on 334 members — `rect` and `size` on every view among them
			readonly lineCount: number;

			// the real package removes an inherited member by redeclaring it as never — it does
			// this to View.add on Label exactly as written here, and 765 times in all. A label
			// has no children, so `add` is not one of its attributes
			add: never;

			addEventListener<K extends keyof LabelEventMap>(name: K, callback: (event: LabelEventMap[K]) => void): void;
			addEventListener (name: string, callback: () => void): void;
		}

		class ImageView extends View {
			image: string;
			// reads exactly like an image property and holds a boolean. The real package has this
			// on ImageView too, beside `image`, which is what makes a name-only rule unsafe
			preventDefaultImage: boolean;
		}

		class Window extends View {
			title: string;
			open (): void;
			close (): void;
		}

		// the platform namespaces the real package nests under UI. The implementation being
		// replaced folded these by hand and missed them, so `Ti.UI.iOS.` answered nothing; here
		// they are namespaces like any other and a regression test says so
		namespace iOS {
			class NavigationWindow extends View {
				openWindow (window: Window): void;
			}

			function createNavigationWindow (options?: Partial<NavigationWindow>): NavigationWindow;
		}

		namespace iPad {
			class SplitWindow extends View {
				masterView: View;
			}

			function createSplitWindow (options?: Partial<SplitWindow>): SplitWindow;
		}

		class ActivityIndicator extends View {
			message: string;
		}

		// real types with no createX factory, mirroring the published package — it has six in
		// Ti.UI, these two among them. A tag is something Alloy can construct, so neither of these
		// is one, and without that rule both would be offered as tags
		class ListItem extends View {
			itemId: string;
		}

		class Clipboard {
			clearText (): void;
		}

		/** Creates a label */
		function createLabel (options?: Partial<Label>): Label;
		function createActivityIndicator (options?: Partial<ActivityIndicator>): ActivityIndicator;
		function createView (options?: Partial<View>): View;
		function createImageView (options?: Partial<ImageView>): ImageView;
		function createWindow (options?: Partial<Window>): Window;
	}

	namespace App {
		const id: string;
	}
}

declare const Ti: typeof Titanium;
